const LABELS=Object.fromEntries(INGREDIENTS.map(i=>[i.key,i.label.toLowerCase()]));

/* How to recognise each fridge item inside a recipe (edit these if you add recipes) */
const text=r=>(r.name+' '+r.ingredients.join(' ')).toLowerCase();
const MATCHERS={
  apple:r=>/\bapple/.test(text(r)),
  tomato:r=>/tomato/.test(text(r)),
  vegetables:r=>r.categories.includes('Vegetables')||/carrot|cucumber/.test(text(r)),
  potato:r=>/potato/.test(text(r)),
  cheese:r=>r.categories.includes('Cheese')||/cheese|feta|mozzarella|cheddar/.test(text(r)),
  minced:r=>/minced/.test(text(r)),
  chicken:r=>/chicken/.test(text(r)),
  milk:r=>/\bmilk\b/.test(text(r)),
  onion:r=>/(?<!spring )onions?\b|garlic|shallot/.test(text(r)),
  bread:r=>/\bbread\b|toastie/.test(text(r)),
  tuna:r=>/\btuna\b/.test(text(r)),
  eggs:r=>/\beggs?\b/.test(text(r)),
  rice:r=>/\brice\b/.test(text(r)),
  pasta:r=>r.categories.includes('Pasta')||/pasta|spaghetti|noodles/.test(text(r))
};
/* Rough nutrition tags (my estimates: about 20 g protein or more per serving = high protein, about 350 kcal or less = low calorie). Check them against your own numbers. */
const DIETS={21:['highprotein'],19:['highprotein'],13:['highprotein'],14:['highprotein'],15:['highprotein'],11:['highprotein'],7:['lowcal'],3:['lowcal'],6:['lowcal'],10:['lowcal']};
function prep(r){r.has=new Set(Object.keys(MATCHERS).filter(k=>MATCHERS[k](r)));if(!r.custom){const t=r.tags.split(' ');r.vegan=t.includes('vegan');r.veg=r.vegan||t.includes('vegetarian');const d=DIETS[r.id]||[];r.hp=d.includes('highprotein');r.lc=d.includes('lowcal')}}
recipes.forEach(prep);

/* ===== State ===== */
const $=s=>document.querySelector(s);
const reduceMotion=()=>matchMedia('(prefers-reduced-motion:reduce)').matches;
let saved=[],ratings={},checks={},persistent=true;
try{const s=JSON.parse(localStorage.getItem('scrappy-saved')||'[]'),r=JSON.parse(localStorage.getItem('scrappy-ratings')||'{}');saved=Array.isArray(s)?s.filter(x=>recipes.some(y=>y.id===x)):[];if(r&&typeof r==='object')for(const [id,n]of Object.entries(r))if(Number.isInteger(n)&&n>=1&&n<=5)ratings[id]=n;}catch{persistent=false}
const F={diet:'any',time:'any'};
let selected=new Set(),view='all',current=null,toastTimer,opener=null;
function persist(){try{localStorage.setItem('scrappy-saved',JSON.stringify(saved));localStorage.setItem('scrappy-ratings',JSON.stringify(ratings))}catch{persistent=false}}
function toast(message){$('#toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',2800)}
const PLACEHOLDER='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><rect width="100" height="100" fill="#f6c45e"/><text x="50" y="64" font-size="44" text-anchor="middle">🍽️</text></svg>');
function photo(r,lazy=true){return `<img src="${r.photo||(r.image?r.image:PLACEHOLDER)}" alt="${esc(r.name)}" ${lazy?'loading="lazy"':''} width="600" height="600" onerror="this.onerror=null;this.src=PLACEHOLDER">`}

/* ===== Build the fridge ===== */
const ingButton=i=>`<button class="ing" type="button" data-ingredient="${i.key}" aria-pressed="false" style="left:${i.x}%;top:${i.y}%${i.w?`;width:${i.w}%;height:${i.h}%`:''}"><svg viewBox="0 0 100 100" aria-hidden="true">${i.svg}</svg><span class="ing-name">${i.label}</span>${i.sub?`<span class="ing-sub">${i.sub}</span>`:''}</button>`;
$('#fridgeItems').innerHTML=INGREDIENTS.map(ingButton).join('');
function syncFridge(){document.querySelectorAll('[data-ingredient]').forEach(b=>b.setAttribute('aria-pressed',selected.has(b.dataset.ingredient)))}
/* the door swings open right after the footsteps end, once the top of the fridge reaches the middle of the screen */
(function(){const scene=$('#fridgeScene');
  if(reduceMotion()){scene.classList.add('open');return}
  let done=false;
  function check(){if(done)return;const r=scene.getBoundingClientRect();
    if(r.top<=innerHeight*.55&&r.bottom>0){done=true;scene.classList.add('open');removeEventListener('scroll',check);removeEventListener('resize',check)}}
  addEventListener('scroll',check,{passive:true});addEventListener('resize',check);check()})();

/* footsteps appear step by step as you scroll toward the fridge (and fade back if you scroll up) */
(function(){const t=document.querySelector('.trail');if(!t)return;
  const fps=[...t.querySelectorAll('.fp')];
  if(reduceMotion()){t.classList.add('all');return}
  let tick=false;
  function update(){tick=false;const r=t.getBoundingClientRect(),vh=innerHeight,start=vh*.85,end=vh*.7;
    const p=Math.max(0,Math.min(1,(start-r.top)/((start-end)+r.height)));
    const n=Math.ceil(p*fps.length);fps.forEach((f,i)=>f.classList.toggle('on',i<n))}
  addEventListener('scroll',()=>{if(!tick){tick=true;requestAnimationFrame(update)}},{passive:true});
  addEventListener('resize',update);update()})();

/* ===== Filtering ===== */
const score=r=>[...selected].filter(k=>r.has.has(k)).length;
function matches(ignoreView){
  const q='',diet=F.diet,time=F.time,closest=$('#closest').checked;
  let list=recipes.filter(r=>
    (ignoreView||view==='all'||saved.includes(r.id))&&
    (closest?(!selected.size||score(r)>0):score(r)===selected.size)&&
    (diet==='any'||(diet==='vegetarian'?r.veg:diet==='vegan'?r.vegan:diet==='highprotein'?r.hp:r.lc))&&
    (time==='any'||r.time<=+time)&&
    (!q||(r.name+' '+r.tags+' '+r.ingredients.join(' ')).toLowerCase().includes(q)));
  const sort=$('#sort').value;
  if(sort==='time')list.sort((a,b)=>a.time-b.time);
  else if(sort==='rank')list.sort((a,b)=>(+ratings[b.id]||0)-(+ratings[a.id]||0));
  else if(closest&&selected.size)list.sort((a,b)=>score(b)-score(a));
  return list;
}
function ratingMarkup(r){let n=Number(ratings[r.id])||0;return `<span class="rating" aria-label="${n?n+' out of 5, your rating':'Not yet rated out of 5'}">${'★'.repeat(n)+'☆'.repeat(5-n)} <small>${n?n+'/5':'Not rated'}</small></span>`}
function cardHTML(r,i){
  const got=score(r),total=selected.size;
  const meter=total&&$('#closest').checked?`<p class="match">You have ${got} of ${total} picks <span aria-hidden="true">${'●'.repeat(got)+'○'.repeat(total-got)}</span></p>`:'';
  const on=saved.includes(r.id);
  return `<article class="card" style="--i:${i}"><button class="recipe-open" data-open="${r.id}" aria-label="View ${esc(r.name)}"><h3>${esc(r.name)}</h3><div class="picture">${photo(r)}<span class="time-tag"><b>${r.time}</b>min</span></div></button><div class="card-info">${ratingMarkup(r)}<span class="difficulty">Easy</span></div>${meter}<div class="card-bottom"><span>Serves ${r.serves}${r.custom?' · <strong>My recipe</strong>':''}</span><button class="heart" data-save="${r.id}" aria-pressed="${on}" aria-label="${on?'Unsave':'Save'} ${esc(r.name)}">${on?'♥':'♡'}</button></div></article>`;
}
function render(opts={}){
  const list=matches();
  $('#savedCount').textContent=saved.length;
  $('#allTab').classList.toggle('active',view==='all');$('#savedTab').classList.toggle('active',view==='saved');
  $('#allTab').setAttribute('aria-pressed',view==='all');$('#savedTab').setAttribute('aria-pressed',view==='saved');
  $('#resultsTitle').textContent=view==='saved'?'Your little recipe book.':'Your next good meal.';
  const names=[...selected].map(k=>LABELS[k]).join(' + ');
  $('#resultCount').textContent=`${list.length} easy recipe${list.length===1?'':'s'}${selected.size?' with '+names:''}${selected.size&&$('#closest').checked?' (closest matches first)':''}${list.length&&list.every(r=>r.time<=30)?' · all ready in 30 minutes or less':''}`;
  const n=matches(true).length;
  $('#fridgeHint').textContent=selected.size?`${selected.size} picked · ${n} recipe${n===1?'':'s'} match${n===1?'es':''}`:'Tap the ingredients you have. Pick as many as you like.';
  const grid=$('#grid');grid.classList.toggle('fade',!!opts.fade&&!reduceMotion());
  const savedEmpty=view==='saved'&&!saved.length;
  grid.innerHTML=list.length?list.map(cardHTML).join(''):`<div class="empty"><h3>${savedEmpty?'A little empty. A lot of potential.':'Nothing simmering here yet.'}</h3><p>${savedEmpty?'Tap a heart on any recipe to keep it here.':'No recipes match that combination yet. Try fewer ingredients or loosen a filter.'}</p>${!savedEmpty&&selected.size>1&&!$('#closest').checked?'<button class="chip" id="emptyClosest" type="button">Show closest matches</button>':''}<button class="chip" id="emptyReset" type="button">Browse all recipes ↗</button></div>`;
  renderTP();
}
const QUICK={time:{key:'time',val:'15'},veg:{key:'diet',val:'vegetarian'},protein:{key:'diet',val:'highprotein'},lowcal:{key:'diet',val:'lowcal'}};
function syncQuick(){
  document.querySelectorAll('[data-quick]').forEach(b=>{const q=QUICK[b.dataset.quick];b.setAttribute('aria-pressed',F[q.key]===q.val)});
  document.querySelectorAll('[data-diet]').forEach(b=>b.setAttribute('aria-pressed',F.diet===b.dataset.diet));
  document.querySelectorAll('[data-time]').forEach(b=>b.setAttribute('aria-pressed',F.time===b.dataset.time));
}
function refresh(){syncFridge();syncQuick();render({fade:true})}

function toggleSave(id){const was=saved.includes(id);saved=was?saved.filter(x=>x!==id):[...saved,id];persist();render();if($('#recipeDialog').open)refreshPage(id);
  if(!was){const c=$('#savedCount');c.classList.remove('bump');void c.offsetWidth;c.classList.add('bump');const h=document.querySelector(`[data-save="${id}"]`);if(h)h.classList.add('pop')}
  toast(saved.includes(id)?persistent?'Recipe saved on this device.':'Recipe saved for this visit.':'Recipe removed from saved.')}
/* ===== Recipe catalogue: swipe or use the arrows to move to the next recipe ===== */
let pages=[],pageIndex=0,scrollTimer;
function pageHTML(r,i,n){
  checks[r.id]??=[];
  const tags=[r.vegan?'Vegan':r.veg?'Vegetarian':'',r.hp?'High protein':'',r.lc?'Low calorie':''].filter(Boolean).join(' · ')||'Home cooking';
  return `<article class="rpage" data-rid="${r.id}" role="group" aria-roledescription="slide" aria-label="Recipe ${i+1} of ${n}: ${esc(r.name)}"><div class="rpage-in"><div class="eyebrow">Easy food. Happy days.</div><div class="title-row"><h2>${esc(r.name)}</h2><button class="save" type="button" data-dsave="${r.id}"></button></div><div class="metrics"><div><strong>${r.time} mins</strong><span>estimated total time</span></div><div class="serv-tile"><div class="stepper"><button type="button" data-serv="-1" aria-label="Fewer servings">−</button><strong class="serv-n">${servText(sv(r))}</strong><button type="button" data-serv="1" aria-label="More servings">+</button></div><span>tap + or − to scale the ingredients</span></div><div><strong>${tags}</strong></div></div>${nutriHTML(r)}<div class="detail-columns"><div><div class="detail-picture">${photo(r,false)}</div><div class="ingredients"><h3>What you'll need</h3><p style="font-size:12px">Tick what you already have. <span class="check-count"></span></p><div class="ing-list">${ingLabels(r)}</div><button class="find shop-add" type="button" data-shop="${r.id}">Add the rest to my shopping list</button></div></div><div class="instructions"><h3>Let's get cooking.</h3><button class="find cook-start" type="button" data-cook="${r.id}">Start cook mode</button><ol>${r.steps.map(x=>`<li><span>${esc(x)}</span></li>`).join('')}</ol>${swapHTML(r)}<div class="rate-box"><strong>How did it go?</strong><p>Your rating: <span class="rating-text"></span></p><div class="rate-buttons" role="group" aria-label="Rate this recipe">${[1,2,3,4,5].map(m=>`<button type="button" data-rate="${m}" aria-label="Rate ${m} out of 5">☆</button>`).join('')}</div><p class="storage-note">Saved recipes and ratings stay in this browser when storage is available. Ingredient ticks last for this visit.</p><p class="storage-note">Photos are visual references; toppings may differ from the simple ingredient list.</p><p class="storage-note">Check ingredient labels for allergens and suitability for your diet.</p>${r.custom?`<button class="clear" type="button" data-delete="${r.id}">Delete this recipe</button>`:''}</div></div></div></div></article>`;
}
const pageOf=id=>document.querySelector(`.rpage[data-rid="${id}"]`);
function refreshPage(id){
  const p=pageOf(id),r=recipes.find(x=>x.id===id);if(!p||!r)return;
  p.querySelector('.check-count').textContent=`${checks[id].length}/${r.ingredients.length} ready.`;
  const n=Number(ratings[id])||0;p.querySelector('.rating-text').textContent=n?n+'/5':'Not rated yet';
  p.querySelectorAll('[data-rate]').forEach(b=>{b.textContent=+b.dataset.rate<=n?'★':'☆';b.setAttribute('aria-pressed',+b.dataset.rate===n)});
  const s=p.querySelector('[data-dsave]'),on=saved.includes(id);s.textContent=on?'♥ Saved':'♡ Save recipe';s.setAttribute('aria-pressed',on);
}
function syncNav(){
  current=pages[pageIndex];
  $('#catCount').textContent=`${pageIndex+1} of ${pages.length}`;
  $('#prevRecipe').disabled=pageIndex===0;$('#nextRecipe').disabled=pageIndex===pages.length-1;
  const r=recipes.find(x=>x.id===current);if(r)$('#recipeDialog').setAttribute('aria-label',r.name);
  document.querySelectorAll('.rpage').forEach((p,i)=>{p.inert=i!==pageIndex});
}
function goTo(i,smooth){
  i=Math.max(0,Math.min(pages.length-1,i));const c=$('#detail'),soft=smooth&&!reduceMotion();
  c.scrollTo({left:i*c.clientWidth,behavior:soft?'smooth':'auto'});
  if(!soft){pageIndex=i;syncNav()}else{pageIndex=i;syncNav()}
}
function openRecipe(id,list){
  list=list||matches();pages=list.map(r=>r.id);if(!pages.includes(id))pages.unshift(id);
  opener=document.activeElement;
  $('#detail').innerHTML=pages.map((pid,i)=>pageHTML(recipes.find(r=>r.id===pid),i,pages.length)).join('');
  pages.forEach(refreshPage);
  const d=$('#recipeDialog');if(!d.open)d.showModal();
  goTo(pages.indexOf(id),false);
}
$('#detail').addEventListener('scroll',()=>{clearTimeout(scrollTimer);scrollTimer=setTimeout(()=>{const c=$('#detail'),i=Math.round(c.scrollLeft/c.clientWidth);if(i!==pageIndex&&i>=0&&i<pages.length){pageIndex=i;syncNav()}},80)},{passive:true});
addEventListener('resize',()=>{if($('#recipeDialog').open)goTo(pageIndex,false)});
$('#prevRecipe').onclick=()=>goTo(pageIndex-1,true);
$('#nextRecipe').onclick=()=>goTo(pageIndex+1,true);
$('#recipeDialog').addEventListener('keydown',e=>{if(e.target.matches('input[type=text],textarea,select'))return;if(e.key==='ArrowRight'){e.preventDefault();goTo(pageIndex+1,true)}else if(e.key==='ArrowLeft'){e.preventDefault();goTo(pageIndex-1,true)}});

/* ===== Create my own recipe ===== */
function saveCustom(){try{localStorage.setItem('scrappy-custom',JSON.stringify(recipes.filter(r=>r.custom).map(r=>({id:r.id,name:r.name,time:r.time,serves:r.serves,ingredients:r.ingredients,steps:r.steps,photo:r.photo||'',tags:'',veg:r.veg,vegan:r.vegan,hp:r.hp,lc:r.lc,custom:true}))));return true}catch{return false}}
function deleteRecipe(id){const i=recipes.findIndex(r=>r.id===id&&r.custom);if(i<0)return;recipes.splice(i,1);saved=saved.filter(x=>x!==id);delete ratings[id];persist();saveCustom();$('#recipeDialog').close();refresh();toast('Recipe deleted.')}
function readPhoto(file){return new Promise(done=>{if(!file)return done('');const fr=new FileReader();fr.onerror=()=>done('');fr.onload=()=>{const img=new Image();img.onerror=()=>done('');img.onload=()=>{const s=Math.min(img.width,img.height),c=document.createElement('canvas');c.width=c.height=600;c.getContext('2d').drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,600,600);done(c.toDataURL('image/jpeg',.8))};img.src=fr.result};fr.readAsDataURL(file)})}
const lines=t=>t.split('\n').map(x=>x.trim()).filter(Boolean);
$('#createForm').addEventListener('submit',async e=>{
  e.preventDefault();
  const name=$('#cName').value.trim(),ing=lines($('#cIngredients').value),steps=lines($('#cSteps').value),msg=$('#createMsg');
  if(!name||!ing.length||!steps.length){msg.textContent='Add a name, at least one ingredient and at least one step.';return}
  msg.textContent='Adding your recipe…';
  const r={id:Date.now(),name,time:Math.max(1,Math.round(+$('#cTime').value)||20),serves:Math.max(1,Math.round(+$('#cServes').value)||2),ingredients:ing,steps,photo:await readPhoto($('#cPhoto').files[0]),tags:'',categories:[],custom:true,vegan:$('#dVegan').checked,veg:$('#dVeg').checked||$('#dVegan').checked,hp:$('#dHp').checked,lc:$('#dLc').checked};
  prep(r);recipes.push(r);const ok=saveCustom();
  $('#createForm').reset();msg.textContent='';
  view='all';$('#sort').value='default';selected.clear();F.diet='any';F.time='any';$('#closest').checked=false;
  refresh();go('home');setTimeout(()=>scrollToId('results'),60);
  toast(ok?'Recipe added. It stays on this device.':'Recipe added for this visit only (browser storage is full or blocked).');
});
function reset(){selected.clear();$('#sort').value='default';F.diet='any';F.time='any';$('#closest').checked=false;refresh()}


/* ===== Nutrition per serving (my rough estimates: kcal, protein g, carbs g, fat g). Check them against your own numbers. ===== */
const NUTRITION={21:[690,30,70,29],13:[520,34,62,13],3:[320,21,4,24],14:[480,32,36,22],15:[640,36,78,18],6:[340,11,56,8],7:[310,11,36,14],19:[430,31,30,20],9:[520,17,62,22],10:[290,17,14,19],11:[480,30,62,10],12:[450,17,40,24],18:[380,4,58,15],20:[300,3,38,15],16:[380,15,40,17],22:[470,14,66,16]};

/* ===== Swap tips: "no X? use Y" for the recipes ===== */
const SWAPS={
  21:["No bacon or pancetta? Diced ham, chorizo or fried mushrooms all work (mushrooms make it vegetarian).","No Parmesan? Any hard cheese will do: pecorino, Grana Padano or a strong cheddar.","No spaghetti? Any pasta shape works."],
  13:["No chicken? Use tofu, extra egg, ham or leftover cooked meat.","No frozen peas? Sweetcorn, green beans or any chopped veg.","Day-old cold rice fries better than freshly cooked rice.","No soy sauce? A splash of Worcestershire sauce and a pinch of salt."],
  3:["No spinach? Kale, rocket or frozen spinach (squeeze it dry first).","No feta? Goat's cheese, grated cheddar or mozzarella.","Add peppers or mushrooms if the fridge needs emptying."],
  14:["No chicken? Black beans, sweetcorn or leftover roast veg.","No cheddar? Mozzarella melts best, or mix whatever cheese you have.","No smoked paprika? Regular paprika or a pinch of cumin.","No salsa? Chopped tomato with a squeeze of lime."],
  15:["No minced beef? Minced turkey, green lentils or finely chopped mushrooms.","No Italian herbs? Dried oregano or basil, or mixed herbs.","No canned tomatoes? 3 fresh tomatoes, chopped, or a splash of passata.","No spaghetti? Any pasta shape works."],
  6:["No sweet potatoes? Regular potatoes work, just bake them a little longer.","No chickpeas? Black beans or canned lentils.","No yogurt? Sour cream or a spoonful of hummus.","No smoked paprika? Regular paprika or chilli flakes."],
  7:["No chickpeas? White beans or lentils.","No parsley? Mint, coriander or spring onion.","No lemon? Lime or a splash of vinegar.","No cucumber? Pepper or celery for the crunch."],
  19:["No cooked chicken? Canned tuna, chickpeas or leftover roast veg.","No avocado? Mashed chickpeas mixed with yogurt or hummus gives the same creaminess.","No lime? Lemon, or a drop of vinegar.","No wraps? Use pitta or make it a sandwich."],
  9:["No peanut butter? Tahini or almond butter.","No fresh pepper? Frozen stir-fry veg or any veg you have.","No noodles? Spaghetti or rice work fine.","No soy sauce? A pinch of salt and a splash of vinegar."],
  10:["No canned tomatoes? Passata, or fresh tomatoes cooked a little longer.","No cumin? Paprika or just black pepper.","No onion? Spring onion, or skip it.","Crumble in feta or add chilli flakes if you have them."],
  11:["No tuna? Canned salmon, chickpeas or leftover chicken.","No sweetcorn? Peas or diced pepper.","No lemon? Lime or a splash of vinegar."],
  12:["No pesto? Blend basil with olive oil, or spread on a little tomato paste.","No mozzarella? Cheddar or any melting cheese.","No fresh tomato? Sun-dried tomatoes or a spoon of tomato paste."],
  18:["No oats? Extra flour, or crushed biscuits or cornflakes.","No apples? Pears, plums or frozen berries.","No cinnamon? Mixed spice or a little vanilla.","Vegan? Use plant butter or coconut oil."],
  20:["No chocolate chips? Chop up a chocolate bar.","No bicarbonate of soda? About 1 tsp baking powder works.","No brown sugar? All caster sugar works, the cookies just get a little less chewy."],
  22:["No buttermilk? Milk plus a spoonful of lemon juice or vinegar works the same way.","No bicarbonate of soda? Use 2 tsp baking powder in total.","No butter? Any neutral oil works for the pan and the batter.","Lumpy batter is fine: overmixing makes pancakes tough.","Top with sliced banana, berries or jam instead of maple syrup."],
  16:["No milk? Any plant milk or a splash of water.","No maple syrup? Honey, jam or sliced banana.","Stale bread works best because it soaks up the egg without falling apart.","No cinnamon? A little vanilla, or leave it out."]
};

/* ===== Servings scaler ===== */
const servings={};
const sv=r=>servings[r.id]||r.serves;
const FRAC={'¼':.25,'½':.5,'¾':.75,'⅓':1/3,'⅔':2/3};
function fmtQty(n,metric){
  if(metric)return String(n>=50?Math.round(n/5)*5:Math.max(1,Math.round(n)));
  const q=Math.max(1,Math.round(n*4))/4,w=Math.floor(q),f=q-w;
  return (w?String(w):'')+(f===.25?'¼':f===.5?'½':f===.75?'¾':'')||'¼';
}
const PLURAL=[[/^egg\b/,'eggs'],[/^carrot\b/,'carrots'],[/^garlic clove\b/,'garlic cloves'],[/^tomato\b/,'tomatoes'],[/^ripe avocado\b/,'ripe avocados'],[/^pepper\b/,'peppers'],[/^can\b/,'cans'],[/^slice\b/,'slices']];
const SINGLE=[[/^eggs\b/,'egg'],[/^carrots\b/,'carrot'],[/^garlic cloves\b/,'garlic clove'],[/^tomatoes\b/,'tomato'],[/^apples\b/,'apple'],[/^slices\b/,'slice'],[/^medium sweet potatoes\b/,'medium sweet potato'],[/^large flour tortillas\b/,'large flour tortilla'],[/^large tortilla wraps\b/,'large tortilla wrap'],[/^spring onions\b/,'spring onion']];
function scaleLine(s,f){
  if(f===1)return s;
  const m=s.match(/^(\d+(?:\.\d+)?)?\s?([¼½¾⅓⅔])?\s*/);
  if(!m||(!m[1]&&!m[2]))return s;
  const q=(+m[1]||0)+(FRAC[m[2]]||0)||0;if(!q)return s;
  let rest=s.slice(m[0].length);
  const metric=/^(g|kg|ml|l)\b/.test(rest),n=q*f,out=fmtQty(n,metric);
  if(!metric){const many=n>1.01;for(const [re,to] of many?PLURAL:SINGLE)if(re.test(rest)){rest=rest.replace(re,to);break}}
  rest=rest.replace(/\(about (\d+) (g|ml)\)/,(x,a,u)=>`(about ${fmtQty(+a*f,true)} ${u})`);
  return out+' '+rest;
}
const ingLabels=r=>{const f=sv(r)/r.serves;return r.ingredients.map((x,k)=>`<label><input type="checkbox" data-check="${k}" ${checks[r.id].includes(k)?'checked':''}><span>${esc(scaleLine(x,f))}</span></label>`).join('')};
const servText=n=>n+(n===1?' serving':' servings');
function nutriHTML(r){const n=NUTRITION[r.id];if(!n)return '';return `<div class="nutri"><h3>Nutrition per serving</h3><div class="nutri-grid"><div><strong>${n[0]}</strong><span>kcal</span></div><div><strong>${n[1]} g</strong><span>protein</span></div><div><strong>${n[2]} g</strong><span>carbs</span></div><div><strong>${n[3]} g</strong><span>fat</span></div></div><p class="storage-note">Rough estimates worked out by hand, not lab values.</p></div>`}
function swapHTML(r){const s=SWAPS[r.id];if(!s)return '';return `<aside class="swap"><h3>Swap tips</h3><ul>${s.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></aside>`}

/* ===== Shopping list ===== */
let shop=[];
try{const s=JSON.parse(localStorage.getItem('scrappy-shop')||'[]');if(Array.isArray(s))shop=s.filter(x=>x&&typeof x.t==='string').map(x=>({t:x.t.slice(0,120),done:!!x.done}))}catch{}
function saveShop(){try{localStorage.setItem('scrappy-shop',JSON.stringify(shop))}catch{}}
function shopRender(){
  $('#shopCount').textContent=shop.filter(x=>!x.done).length;
  $('#shopList').innerHTML=shop.length?shop.map((x,i)=>`<li><label><input type="checkbox" data-sdone="${i}" ${x.done?'checked':''}><span>${esc(x.t)}</span></label><button type="button" class="x" data-sdel="${i}" aria-label="Remove ${esc(x.t)}">✕</button></li>`).join(''):'<li class="empty-shop">Nothing here yet. Open a recipe, tick what you already have, then add the rest.</li>';
}
function addToShop(id,btn){
  const r=recipes.find(x=>x.id===id);if(!r)return;
  const f=sv(r)/r.serves,have=new Set(shop.map(x=>x.t.toLowerCase()));let n=0;
  r.ingredients.forEach((x,k)=>{if(checks[id].includes(k))return;const t=scaleLine(x,f);if(have.has(t.toLowerCase()))return;have.add(t.toLowerCase());shop.push({t,done:false});n++});
  saveShop();shopRender();
  btn.textContent=n?`Added ${n} item${n===1?'':'s'} ✓`:'Nothing new to add ✓';
  setTimeout(()=>{btn.textContent='Add the rest to my shopping list'},2200);
}
$('#shopTab').onclick=()=>{$('#shopCopyArea').hidden=true;$('#shopDialog').showModal()};
$('#closeShop').onclick=()=>$('#shopDialog').close();
$('#shopDialog').addEventListener('click',e=>{if(e.target===$('#shopDialog')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close()}});
$('#shopForm').addEventListener('submit',e=>{e.preventDefault();const i=$('#shopInput'),t=i.value.trim().slice(0,120);if(!t)return;shop.push({t,done:false});i.value='';saveShop();shopRender()});
$('#shopList').addEventListener('change',e=>{if(e.target.matches('[data-sdone]')){shop[+e.target.dataset.sdone].done=e.target.checked;saveShop();shopRender()}});
$('#shopList').addEventListener('click',e=>{const d=e.target.closest('[data-sdel]');if(d){shop.splice(+d.dataset.sdel,1);saveShop();shopRender()}});
$('#shopClearDone').onclick=()=>{shop=shop.filter(x=>!x.done);saveShop();shopRender()};
$('#shopClearAll').onclick=()=>{shop=[];saveShop();shopRender()};
$('#shopCopy').onclick=()=>{
  const text=shop.filter(x=>!x.done).map(x=>'- '+x.t).join('\n');if(!text){$('#shopCopy').textContent='List is empty';setTimeout(()=>$('#shopCopy').textContent='Copy list',1600);return}
  const fallback=()=>{const a=$('#shopCopyArea');a.value=text;a.hidden=false;a.select()};
  try{navigator.clipboard.writeText(text).then(()=>{$('#shopCopy').textContent='Copied ✓';setTimeout(()=>$('#shopCopy').textContent='Copy list',1600)},fallback)}catch{fallback()}
};

/* ===== Cook mode: one big step at a time, with timers ===== */
let cook={id:0,i:0,left:0,total:0,end:0,run:false,tm:null,lock:null};
const mmss=s=>String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');
const stepMinutes=t=>{const m=t.match(/(\d+)(?:\s?[–-]\s?(\d+))?\s*(?:minutes?|mins?)\b/i);return m?+(m[2]||m[1]):0};
function stopTimer(){clearInterval(cook.tm);cook.run=false}
function cookRender(){
  const r=recipes.find(x=>x.id===cook.id),n=r.steps.length;stopTimer();
  $('#cookName').textContent=r.name;$('#cookCount').textContent=`Step ${cook.i+1} of ${n}`;$('#cookStep').textContent=r.steps[cook.i];
  const m=stepMinutes(r.steps[cook.i]);cook.total=m*60;cook.left=cook.total;
  $('#cookTimer').hidden=!m;$('#cookTimer').classList.remove('done');$('#cookClock').textContent=mmss(cook.left);$('#cookGo').textContent='Start timer';
  $('#cookPrev').disabled=cook.i===0;$('#cookNext').textContent=cook.i===n-1?'All done ✓':'Next step →';
  const f=sv(r)/r.serves;$('#cookIngs').innerHTML=r.ingredients.map(x=>`<li>${esc(scaleLine(x,f))}</li>`).join('');
}
function startCook(id){cook.id=id;cook.i=0;cookRender();$('#cookDialog').showModal();try{navigator.wakeLock&&navigator.wakeLock.request('screen').then(l=>{cook.lock=l}).catch(()=>{})}catch{}}
function beep(){try{const a=new (window.AudioContext||window.webkitAudioContext)();[0,.35,.7].forEach(t=>{const o=a.createOscillator(),g=a.createGain();o.frequency.value=880;o.connect(g);g.connect(a.destination);g.gain.setValueAtTime(.2,a.currentTime+t);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+t+.25);o.start(a.currentTime+t);o.stop(a.currentTime+t+.3)})}catch{}}
$('#cookGo').onclick=()=>{
  if(cook.run){stopTimer();$('#cookGo').textContent='Resume';return}
  if(cook.left<=0)cook.left=cook.total;
  $('#cookTimer').classList.remove('done');cook.end=Date.now()+cook.left*1000;cook.run=true;$('#cookGo').textContent='Pause';
  cook.tm=setInterval(()=>{cook.left=Math.max(0,Math.ceil((cook.end-Date.now())/1000));$('#cookClock').textContent=mmss(cook.left);
    if(!cook.left){stopTimer();$('#cookGo').textContent='Start again';$('#cookTimer').classList.add('done');$('#cookClock').textContent='Time’s up!';beep()}},250);
};
$('#cookReset').onclick=()=>{stopTimer();cook.left=cook.total;$('#cookTimer').classList.remove('done');$('#cookClock').textContent=mmss(cook.left);$('#cookGo').textContent='Start timer'};
$('#cookPrev').onclick=()=>{if(cook.i>0){cook.i--;cookRender()}};
$('#cookNext').onclick=()=>{const r=recipes.find(x=>x.id===cook.id);if(cook.i<r.steps.length-1){cook.i++;cookRender()}else $('#cookDialog').close()};
$('#closeCook').onclick=()=>$('#cookDialog').close();
$('#cookDialog').addEventListener('close',()=>{stopTimer();try{cook.lock&&cook.lock.release&&cook.lock.release()}catch{}cook.lock=null});
$('#cookDialog').addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();$('#cookNext').click()}else if(e.key==='ArrowLeft'){e.preventDefault();$('#cookPrev').click()}});

/* ===== Clicks inside a recipe page: servings, cook mode, shopping list ===== */
$('#detail').addEventListener('click',e=>{
  const sb=e.target.closest('[data-serv]');
  if(sb){const pg=sb.closest('[data-rid]'),id=+pg.dataset.rid,r=recipes.find(x=>x.id===id),n=Math.max(1,Math.min(12,sv(r)+(+sb.dataset.serv)));servings[id]=n;pg.querySelector('.serv-n').textContent=servText(n);pg.querySelector('.ing-list').innerHTML=ingLabels(r);return}
  const cb=e.target.closest('[data-cook]');if(cb){startCook(+cb.dataset.cook);return}
  const sh=e.target.closest('[data-shop]');if(sh)addToShop(+sh.dataset.shop,sh);
});
shopRender();


/* ===== Hero time picker: a kitchen timer that sets the Time filter ===== */
const TP_ANG={any:-120,'10':-60,'15':0,'20':60,'30':120};
function renderTP(){
  const t=F.time;$('#tpHand').style.transform=`rotate(${TP_ANG[t]??-120}deg)`;
  $('#tpRead').textContent=t==='any'?'Any time':`Up to ${t} minutes`;
}
$('#tpDial').addEventListener('click',e=>{const b=e.target.closest('.tp-stop');if(!b)return;F.time=b.dataset.time;view='all';refresh()});
(function(){const dial=$('#tpDial'),hand=$('#tpHand');let drag=false;
  const angleOf=e=>{const r=dial.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2);return Math.max(-130,Math.min(130,Math.atan2(dx,-dy)*180/Math.PI))};
  const nearest=a=>Object.keys(TP_ANG).reduce((best,k)=>Math.abs(TP_ANG[k]-a)<Math.abs(TP_ANG[best]-a)?k:best,'any');
  dial.addEventListener('pointerdown',e=>{if(e.target.closest('.tp-stop'))return;drag=true;try{dial.setPointerCapture(e.pointerId)}catch{}hand.classList.add('drag');hand.style.transform=`rotate(${angleOf(e)}deg)`});
  dial.addEventListener('pointermove',e=>{if(drag)hand.style.transform=`rotate(${angleOf(e)}deg)`});
  const end=e=>{if(!drag)return;drag=false;hand.classList.remove('drag');F.time=nearest(angleOf(e));view='all';refresh()};
  dial.addEventListener('pointerup',end);dial.addEventListener('pointercancel',end)})();

/* ===== Background theme switcher: pink opal, baby blue, cream ===== */
function setTheme(t,save){
  if(!['pink','blue','cream'].includes(t))t='pink';
  document.body.dataset.bg=t;
  document.querySelectorAll('.sw').forEach(b=>b.setAttribute('aria-pressed',b.dataset.bg===t));
  if(save){try{localStorage.setItem('scrappy-bg',t)}catch{}}
}
document.querySelector('.themes').addEventListener('click',e=>{const b=e.target.closest('.sw');if(b)setTheme(b.dataset.bg,true)});
(function(){let t='pink';try{t=localStorage.getItem('scrappy-bg')||'pink'}catch{}setTheme(t,false)})();

