function scrollToId(id){const el=document.getElementById(id);if(el)el.scrollIntoView({behavior:reduceMotion()?'auto':'smooth',block:'start'})}
function flash(b){b.classList.remove('flash');void b.offsetWidth;b.classList.add('flash')}
function navTo(b,after){flash(b);setTimeout(after,reduceMotion()?0:260)}
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>navTo(b,()=>{go('home');setTimeout(()=>scrollToId(b.dataset.go),30)})));
