$('#fridgeScene').addEventListener('click',e=>{const b=e.target.closest('[data-ingredient]');if(b)pick(b.dataset.ingredient)});
$('#seeRecipes').onclick=()=>{view='all';render({fade:true});scrollToId('results')};
$('#dietBar').addEventListener('click',e=>{const b=e.target.closest('[data-diet]');if(!b)return;F.diet=b.dataset.diet;view='all';refresh()});
$('#closest').addEventListener('change',()=>render({fade:true}));
$('#sort').addEventListener('change',()=>render({fade:true}));
