$('#grid').addEventListener('click',e=>{const open=e.target.closest('[data-open]'),save=e.target.closest('[data-save]');if(open)openRecipe(+open.dataset.open);if(save){const id=+save.dataset.save;toggleSave(id);const replacement=document.querySelector(`[data-save="${id}"]`);(replacement||$('#savedTab')).focus({preventScroll:true})}
  if(e.target.closest('#emptyClosest')){$('#closest').checked=true;refresh()}
  if(e.target.closest('#emptyReset')){view='all';reset()}});
