$('#recipeDialog').addEventListener('click',e=>{if(e.target===$('#recipeDialog')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close()}});
$('#detail').addEventListener('click',e=>{
  const s=e.target.closest('[data-dsave]');if(s){toggleSave(+s.dataset.dsave);return}
  const b=e.target.closest('[data-rate]');if(b){const id=+b.closest('[data-rid]').dataset.rid;ratings[id]=+b.dataset.rate;persist();refreshPage(id);render();toast('Your rating is '+b.dataset.rate+' out of 5.');return}
  const del=e.target.closest('[data-delete]');if(del){if(del.dataset.armed){deleteRecipe(+del.dataset.delete)}else{del.dataset.armed='1';del.textContent='Click again to delete';setTimeout(()=>{del.dataset.armed='';del.textContent='Delete this recipe'},3500)}}
});
$('#detail').addEventListener('change',e=>{if(e.target.matches('[data-check]')){const id=+e.target.closest('[data-rid]').dataset.rid,i=+e.target.dataset.check;checks[id]=e.target.checked?[...checks[id],i]:checks[id].filter(x=>x!==i);refreshPage(id)}});

/* ===== Surprise me: a spinning roulette, then confetti, then the recipe ===== */
function confetti(host){const colors=['#f6c45e','#b9321a','#e7a0af','#fbf0d9','#ffffff'];for(let i=0;i<32;i++){const s=document.createElement('span');s.className='confetti';const a=Math.random()*Math.PI*2,d=130+Math.random()*220;s.style.cssText=`--x:${Math.cos(a)*d}px;--y:${Math.sin(a)*d}px;--r:${Math.random()*720-360}deg;background:${colors[i%5]}`;host.appendChild(s)}}
$('#surprise').onclick=()=>{
  const list=matches();if(!list.length){toast('Clear your filters to discover a recipe.');return}
  const chosen=list[Math.floor(Math.random()*list.length)];
  if(reduceMotion()){openRecipe(chosen.id,list);return}
  const btn=$('#surprise');btn.disabled=true;
  const ov=document.createElement('div');ov.className='roulette';ov.setAttribute('aria-hidden','true');ov.innerHTML='<div class="plate">🍽️</div><p class="spin-name"></p>';document.body.appendChild(ov);
  const name=ov.querySelector('.spin-name');let i=Math.floor(Math.random()*recipes.length),delay=70;
  (function tick(){
    if(delay>340){name.textContent=chosen.name;name.classList.add('landed');ov.classList.add('done');confetti(ov);toast('Tonight: '+chosen.name);setTimeout(()=>{ov.remove();btn.disabled=false;openRecipe(chosen.id,list)},1300);return}
    name.textContent=recipes[i++%recipes.length].name;delay*=1.13;setTimeout(tick,delay)})();
};

/* Fade-in on scroll for the "How it works" cards */
(function(){const els=document.querySelectorAll('.reveal');if(!('IntersectionObserver'in window)||reduceMotion()){els.forEach(e=>e.classList.add('in'));return}
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.2});els.forEach(e=>io.observe(e))})();

/* ===== Two pages in one: the recipes page and the Create my own recipe page ===== */
function showView(v){const create=v==='create';$('#homeView').hidden=create;$('#createView').hidden=!create;document.title=create?'Create my own recipe · The Scrappy Kitchen':'The Scrappy Kitchen';window.scrollTo(0,0)}
function go(v){const want=v==='create'?'#new-recipe':'';if(v==='create'&&location.hash!==want){location.hash='new-recipe'}else if(v!=='create'&&location.hash==='#new-recipe'){location.hash=''}showView(v)}
$('#openCreate').onclick=()=>go('create');
$('#backHome').onclick=()=>{go('home');setTimeout(()=>scrollToId('results'),30)};
addEventListener('hashchange',()=>showView(location.hash==='#new-recipe'?'create':'home'));
showView(location.hash==='#new-recipe'?'create':'home');
syncFridge();syncQuick();render({fade:true});
